    assert_eq!(0x08, rcon(4));
    assert_eq!(0x10, rcon(5));
    assert_eq!(0x20, rcon(6));
    assert_eq!(0x40, rcon(7));
    assert_eq!(0x80, rcon(8));
    assert_eq!(0x1B, rcon(9));
    assert_eq!(0x36, rcon(10));
}

